  static void ButtonColors(Button button){if(SystemInformation.HighContrast){button.FlatAppearance.BorderColor=SystemColors.WindowText;button.BackColor=SystemColors.Control;button.ForeColor=button.Enabled?SystemColors.ControlText:SystemColors.GrayText;return;}bool primary=button.Text=="保存设备权限"||button.Text=="开启并生成配对二维码";button.FlatAppearance.BorderColor=button.Enabled?Color.FromArgb(88,126,160):Color.FromArgb(111,138,162);button.BackColor=!button.Enabled?Color.FromArgb(150,171,192):primary?Color.FromArgb(37,102,171):Color.FromArgb(43,70,96);button.ForeColor=!button.Enabled?Color.FromArgb(48,67,87):primary?Color.White:TextColor;}
  static void StyleControls(Control parent){foreach(Control child in parent.Controls){var button=child as Button;if(button!=null){button.FlatStyle=FlatStyle.Flat;ButtonColors(button);button.MinimumSize=new Size(100,34);button.Padding=new Padding(7,2,7,2);}if(child is TabPage||child is ListBox||child is ComboBox||child is NumericUpDown){child.BackColor=SurfaceColor;child.ForeColor=TextColor;}StyleControls(child);}}
  Button Button(string text,Action action){var button=new Button{Text=text,AutoSize=true,MinimumSize=new Size(90,32)};button.Click+=(s,e)=>{try{notice.Text="";action();}catch(InvalidOperationException ex){notice.Text=ex.Message;}catch(ArgumentException ex){notice.Text=ex.Message;}catch(UnauthorizedAccessException){notice.Text="没有权限保存伴随屏设置或配对记录，请检查运行目录的写入权限。";}catch(IOException){notice.Text="伴随屏设置或配对记录未能保存，请检查磁盘空间、目录权限及文件是否被占用。";}catch(Exception){notice.Text="操作未完成。请核对服务是否开启、地址是否仍属于此电脑，以及证书和网络配置。";}};return button;}
  async void CreatePairing(){try{if(!await EnsureConnected())return;ClearPairing();string value=host.server.OpenPairing();DrawQr(host.server.Address+"/#pair="+value,false);code.Text="配对码："+value+" · 2 分钟有效";UpdateStatus();}catch(Exception ex){ConnectionError(ex);}}
  void DrawQr(string url,bool entry){ClearPairing();using(var generator=new QRCodeGenerator())using(var data=generator.CreateQrCode(url,QRCodeGenerator.ECCLevel.M))using(var qr=new QRCode(data)){int scale=Math.Max(1,185/data.ModuleMatrix.Count);pairingQr.Image=qr.GetGraphic(scale,Color.Black,Color.White,true);}entryQr=entry;pairingQr.AccessibleName=entry?"iPad 固定连接二维码":"iPad 配对二维码";pairingQr.Visible=true;networkExpanded=false;networkOptions.Visible=false;pairingPanel.Height=215;pairingPanel.Visible=true;pages.SelectedIndex=0;}
  void ClearPairing(){entryQr=false;var image=pairingQr.Image;pairingQr.Image=null;pairingQr.Visible=false;code.Text="";if(image!=null){image.Dispose();pairingPanel.Height=120;pairingPanel.Visible=networkExpanded;}}
  CompanionGrant SelectedGrant(){return new CompanionGrant{apps=grantApps.Checked,music=grantMusic.Checked,control=grantControl.Checked,tasks=grantTasks.Checked,notes=grantNotes.Checked,pointer=grantPointer.Checked,power=grantPower.Checked,screen=grantScreen.Checked,keyboard=grantKeyboard.Checked};}
  void SelectGrant(Choice item,bool isPending){
   if(item==null){UpdateActions();return;}string target=(isPending?"pending:":"device:")+item.id;if(target==grantTarget){UpdateActions();return;}if(grantTarget!="")drafts[grantTarget]=SelectedGrant();grantTarget=target;refreshingLists=true;try{if(isPending)devices.SelectedIndex=-1;else pending.SelectedIndex=-1;}finally{refreshingLists=false;}
   CompanionGrant value;if(!drafts.TryGetValue(target,out value))value=item.grants??new CompanionGrant();loadingGrants=true;try{grantApps.Checked=value.apps;grantMusic.Checked=value.music;grantControl.Checked=value.control;grantTasks.Checked=value.tasks;grantNotes.Checked=value.notes;grantPointer.Checked=value.pointer;grantPower.Checked=value.power;grantScreen.Checked=value.screen;grantKeyboard.Checked=value.keyboard;}finally{loadingGrants=false;}UpdateActions();
  }
  static string GrantKey(CompanionGrant value){return value==null?"":String.Join("|",new[]{value.apps,value.music,value.control,value.tasks,value.notes,value.pointer,value.power,value.screen,value.keyboard});}
  void UpdateActions(){if(saveGrantButton==null)return;var device=devices.SelectedItem as Choice;var request=pending.SelectedItem as Choice;bool selected=device!=null||request!=null;foreach(var box in GrantBoxes())box.Enabled=selected;saveGrantButton.Enabled=device!=null&&GrantKey(SelectedGrant())!=GrantKey(device.grants);revokeButton.Enabled=device!=null;approveButton.Enabled=request!=null;rejectButton.Enabled=request!=null;foreach(var button in new[]{saveGrantButton,revokeButton,approveButton,rejectButton})ButtonColors(button);
   permissionTitle.Text=device!=null?device.name+" 的共享权限":request!=null?"批准 "+request.name:"选择一台设备";permissionHint.Text=device!=null?(saveGrantButton.Enabled?"有未保存的更改 · 点击保存设备权限后生效":"已保存 · 勾选权限后再点击保存"):request!=null?"确认设备名称，选择本次允许共享的内容":pending.Items.Count>0?"请在左侧待批准请求中选择一台设备。":"暂无待批准请求。请先让 iPad 扫码并提交配对。";
  }
  void UpdateGrant(){var item=devices.SelectedItem as Choice;if(item==null){notice.Text="请先选择要更新权限的已授权设备。";return;}host.server.UpdateGrant(item.id,SelectedGrant());drafts.Remove(grantTarget);notice.Text="已更新 "+item.name+" 的共享权限。";UpdateStatus();}
  void Approve(){var item=pending.SelectedItem as Choice;if(item==null){notice.Text=pending.Items.Count==0?"暂无待批准请求。请先让 iPad 扫码并提交配对。":"请先在待批准请求中选择一台设备。";return;}host.server.Approve(item.id,SelectedGrant());drafts.Remove(grantTarget);grantTarget="";notice.Text="已批准 "+item.name+"，请在 iPad 等待连接完成。";UpdateStatus();}
  internal async void RefreshNetwork(){if(readingNetwork||connecting||IsDisposed)return;readingNetwork=true;try{var next=await Task.Run(()=>host.ReadNetworks());if(IsDisposed||connecting)return;networks=next;if(host.activeNetwork!=null&&!next.Any(n=>CompanionConnection.SameNetwork(n,host.activeNetwork))){host.Stop();ClearPairing();notice.Text="网络已变化，连接已暂停。请点“检查并连接”，iPad 固定入口保持不变。";UpdateStatus();}RefreshAddresses();}catch{if(!IsDisposed)notice.Text="暂时无法读取当前网络，请点“检查并连接”重试。";}finally{readingNetwork=false;}}
  void RefreshAddresses(){string selected=address.SelectedItem as string;Dictionary<string,object> record=null;try{record=CompanionConnection.ReadRecord(host.root);}catch{}var choice=CompanionConnection.Select(networks,selected??host.config.address,CompanionConnection.Text(record,"interfaceId"));address.Items.Clear();foreach(var network in networks)address.Items.Add(network.address);if(choice!=null)address.SelectedItem=choice.address;}
  void ConnectionError(Exception ex){if(IsDisposed)return;notice.Text=ex is IOException?"连接设置未能保存，请检查磁盘空间和目录权限。":ex is UnauthorizedAccessException?"连接设置没有写入权限，请使用原来的电脑用户重试。":ex is System.ComponentModel.Win32Exception?"系统配置已取消。可再次点“检查并连接”。":ex is InvalidOperationException||ex is ArgumentException||ex is TimeoutException?ex.Message:"连接未完成，请检查当前网络和电脑端配置。";UpdateStatus();}
  async void Connect(){try{if(!await EnsureConnected())return;string peer;CompanionGrant grant;lock(host.videoGate){peer=host.videoPeer;grant=host.videoGrant;host.videoKey="";}if(grant!=null&&grant.Active&&peer.Length>0)host.PrepareVideo(peer,grant);DrawQr(host.server.Address+"/",true);code.Text="固定入口 · 已配对设备扫码直接打开";UpdateStatus();}catch(Exception ex){ConnectionError(ex);}}
  void ImportPreviousSetup(){if(connecting){notice.Text="连接检查正在进行，请稍后重试。";return;}if(CompanionConnection.ReadRecord(host.root)!=null){notice.Text="此安装已有连接配置，将继续沿用；无需再次导入。";return;}using(var choose=new OpenFileDialog{Title="选择旧版 setup-record.json，沿用 iPad 已信任的证书",Filter="连接配置记录|setup-record.json",CheckFileExists=true}){if(choose.ShowDialog(this)!=DialogResult.OK)return;legacySetup=choose.FileName;}Connect();}
  void ExportCertificate(){byte[] certificate=CompanionConnection.PublicCertificate(host.root);using(var save=new SaveFileDialog{Title="导出公开证书到你选择的位置，再发送给 iPad",FileName="PrismGlass-Companion-CA.cer",Filter="公开证书|*.cer",DefaultExt="cer",AddExtension=true,OverwritePrompt=true}){if(save.ShowDialog(this)!=DialogResult.OK)return;File.WriteAllBytes(save.FileName,certificate);}pages.SelectedIndex=2;notice.Text="公开证书已导出（不包含私钥）。请按连接步骤在 iPad 安装并启用信任，再扫码配对。";}
  async Task<bool> EnsureConnected(){if(connecting)return false;if(host.server.IsRunning&&host.activeNetwork==null){host.StartSources();UpdateStatus();return true;}int attempt=++connectionRevision;connecting=true;address.Enabled=false;port.Enabled=false;
   try{notice.Text="正在检查当前网络与固定入口…";networks=await Task.Run(()=>host.ReadNetworks());if(IsDisposed||attempt!=connectionRevision)return false;if(host.server.IsRunning){if(networks.Any(n=>CompanionConnection.SameNetwork(n,host.activeNetwork))){if(host.discovery.Status=="error"||host.discovery.Status=="stopped"){host.discovery.Stop();var network=host.activeNetwork;host.discovery.Start(network.address,host.config.port,new Uri(host.server.Address).Host,network.index);}host.StartSources();if(!await WaitDiscovery(attempt))return false;notice.Text="";UpdateStatus();return true;}host.Stop();ClearPairing();}RefreshAddresses();var choice=networks.FirstOrDefault(n=>n.address==(address.SelectedItem as string));if(choice==null)throw new InvalidOperationException("没有可用的局域网连接。请先让电脑连接 Wi-Fi 或有线网络。");
    bool trust=false;if(!choice.IsPrivate){if(choice.category!=0)throw new InvalidOperationException("无法确认网络类别，请先在 Windows 网络设置中检查此连接。");if(MessageBox.Show(this,"当前网络："+choice.Description+"\n\n只有你信任的家庭 Wi-Fi 或个人热点才适合开启。是否将此网络设为专用，并继续检查？","确认当前网络",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return false;trust=true;}
    var record=CompanionConnection.ReadRecord(host.root);string name=record==null?proposedHost:CompanionConnection.Text(record,"hostName"),setup=record==null?legacySetup:CompanionConnection.Text(record,"setupRecord");int requestedPort=(int)port.Value;bool initialize=record==null&&String.IsNullOrEmpty(setup);
    var check=await CompanionConnection.Check(host.root,choice,name,requestedPort,setup,trust,initialize);if(IsDisposed||attempt!=connectionRevision)return false;if(!CompanionConnection.Flag(check,"ready"))throw new InvalidOperationException(CompanionConnection.Issues(check));
    if(CompanionConnection.Flag(check,"needsApproval")){string changes="固定入口：https://"+name+":"+requestedPort+"\n网络："+choice.Description+"\n\n"+(initialize?"首次连接：创建专用 CA（3 年）与 HTTPS 证书（1 年），私钥不可导出；配置后需把公开证书安装并信任到 iPad。若以前配置过，请取消并使用“导入旧连接配置”。\n":"沿用 iPad 已信任的 CA。\n")+"为固定名称配置 HTTPS 与当前用户访问权限；只允许此网卡、专用网络、本地子网访问 TCP "+requestedPort+"；UDP 5353 仅允许本安装的 PrismGlass 回答固定名称。\n"+(trust?"将当前网络改为专用。\n":"")+"不修改 Windows 根证书信任。是否应用？";if(MessageBox.Show(this,changes,"配置伴随屏连接",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return false;notice.Text="等待 Windows 管理员确认并配置连接…";await CompanionConnection.Apply(host.root,choice,name,requestedPort,setup,trust,initialize);check=await CompanionConnection.Check(host.root,choice,name,requestedPort,setup,false);if(IsDisposed||attempt!=connectionRevision)return false;if(!CompanionConnection.Flag(check,"configured"))throw new InvalidOperationException("系统配置未通过检查："+CompanionConnection.Issues(check));}
    var current=await Task.Run(()=>host.ReadNetworks());if(IsDisposed||attempt!=connectionRevision)return false;choice=current.FirstOrDefault(n=>n.id==choice.id&&n.address==choice.address&&n.IsPrivate);if(choice==null)throw new InvalidOperationException("网络在检查过程中变化，请再次连接。");Start(choice,name,requestedPort);if(!await WaitDiscovery(attempt))return false;notice.Text=initialize?"电脑配置完成。请在“连接步骤”导出证书，到 iPad 安装并信任后再配对。":"已开启固定入口。首次使用此入口，请生成配对二维码。";return true;
   }finally{connecting=false;if(!IsDisposed){address.Enabled=true;port.Enabled=true;}}
  }
  async Task<bool> WaitDiscovery(int attempt){for(int i=0;i<100;i++){if(IsDisposed||attempt!=connectionRevision||!host.server.IsRunning)return false;if(host.discovery.IsRegistered)return true;if(host.discovery.Status=="error"){string error=host.discovery.Error;host.Stop();throw new InvalidOperationException(error);}await Task.Delay(100);}host.Stop();throw new TimeoutException("固定名称发布超时，请重新检查连接。");}
  void Start(CompanionNetworkChoice choice,string name,int requestedPort){string oldAddress=host.config.address;int oldPort=host.config.port;host.server.Start(choice.address,requestedPort,name);try{host.discovery.Start(choice.address,requestedPort,name,choice.index);host.config.address=choice.address;host.config.port=requestedPort;host.Save();host.activeNetwork=choice;host.StartSources();}catch{host.config.address=oldAddress;host.config.port=oldPort;host.Stop();throw;}UpdateStatus();}
  async void LoadApps(){if(updating)return;updating=true;try{var snapshot=await Task.Run(()=>host.library.GetSnapshot());if(IsDisposed)return;entries=snapshot.entries.Where(e=>e.kind!="action").OrderBy(e=>e.name).ToList();apps.Items.Clear();foreach(var entry in entries){string signature;bool allowed=host.config.apps.TryGetValue(entry.id,out signature)&&signature==CompanionBridge.EntrySignature(entry);apps.Items.Add(entry.name+(entry.exists?"":"（已失效）"),allowed);}}catch{notice.Text="应用列表读取失败，请稍后刷新。";}finally{updating=false;}}
  async void SaveApps(){if(updating)return;var next=new Dictionary<string,string>();foreach(int index in apps.CheckedIndices){var e=entries[index];next[e.id]=CompanionBridge.EntrySignature(e);}if(next.Count>500){notice.Text="最多共享 500 个入口。";return;}updating=true;try{var previous=host.config.apps;host.config.apps=next;try{host.Save();}catch{host.config.apps=previous;throw;}await Task.Run(()=>host.bridge.Allow(next));if(IsDisposed)return;notice.Text="应用共享范围已保存。";}catch{notice.Text="共享范围未能保存，请重新核对。";}finally{updating=false;}}
  void UpdateStatus(){try{var snapshot=host.json.Deserialize<Dictionary<string,object>>(host.json.Serialize(host.server.Status()));DateTime expires;if(!host.server.IsRunning||host.IsLocked()||host.activeNetwork!=null&&host.discovery.Status=="error"||!entryQr&&(!DateTime.TryParseExact(CompanionBridge.Text(snapshot,"pairingExpiresAt"),"o",CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out expires)||expires.ToUniversalTime()<=DateTime.UtcNow))ClearPairing();status.Text=host.server.IsRunning?"访问地址："+host.server.Address+(host.IsLocked()?" · 电脑已锁定":host.discovery.Status=="error"?" · 名称发现失败："+host.discovery.Error:host.activeNetwork!=null&&!host.discovery.IsRegistered?" · 正在发布固定名称…":" · 已开启，等待 iPad 连接"):"服务已关闭 · 每次手动开启 · 关闭或锁屏后停止控制";string key=host.json.Serialize(snapshot);if(key==listKey)return;listKey=key;refreshingLists=true;try{Fill(pending,snapshot,"pending","等待批准 · ");Fill(devices,snapshot,"devices","已授权 · ");}finally{refreshingLists=false;}
   var selected=devices.SelectedItem as Choice;if(selected!=null)SelectGrant(selected,false);else if(pending.SelectedItem!=null)SelectGrant(pending.SelectedItem as Choice,true);else if(devices.Items.Count==1)devices.SelectedIndex=0;else if(pending.Items.Count==1)pending.SelectedIndex=0;else{if(grantTarget!="")drafts.Remove(grantTarget);grantTarget="";UpdateActions();}
  }catch{ClearPairing();status.Text="无法读取伴随屏状态。";}}
  static void Fill(ListBox box,Dictionary<string,object> snapshot,string field,string prefix){var previous=box.SelectedItem as Choice;string selected=previous==null?"":previous.id;box.Items.Clear();object raw;if(!snapshot.TryGetValue(field,out raw))return;var list=raw as System.Collections.IEnumerable;if(list==null)return;foreach(var value in list){var item=value as Dictionary<string,object>;if(item==null)continue;object grant;var serializer=new JavaScriptSerializer();var choice=new Choice{id=CompanionBridge.Text(item,"id"),name=CompanionBridge.Text(item,"name"),label=prefix+CompanionBridge.Text(item,"name"),grants=item.TryGetValue("grants",out grant)?serializer.Deserialize<CompanionGrant>(serializer.Serialize(grant)):null};box.Items.Add(choice);if(choice.id==selected)box.SelectedItem=choice;}}
  protected override void Dispose(bool disposing){if(disposing){refresh.Stop();refresh.Dispose();ClearPairing();}base.Dispose(disposing);}
 }
